    polygon(ctx, paint(0.13), [143,29,168,24,196,29,227,45,187,62,155,57]);
    polygon(ctx, paint(0.01), [93,97,118,82,156,58,188,63,218,50,207,72,169,104,143,115,116,121,100,111]);
    polygon(ctx, paint(-0.25), [128,125,156,102,186,84,216,56,215,67,198,88,169,107,143,120,140,145,148,155,130,152]);
    polygon(ctx, paint(0.05), [221,69,234,81,240,108,235,118,230,93]);
