  polygon(ctx, shade(skin,-0.15), [88,284,105,286,116,294,114,308,104,318,91,316,83,309,83,296]);
  polygon(ctx, shade(skin,0.025), [87,286,104,288,109,296,107,307,100,312,87,309,84,298]);
  polygon(ctx, shade(skin,-0.16), [254,287,272,280,280,289,282,300,274,313,261,315,253,304]);
